  1	//! The first-party personas plugin.
  2	//!
  3	//! Scans the granted personas directories for `*.md` files, parses each
  4	//! one's `+++` TOML frontmatter (`name`, optional `description`) and body,
  5	//! and pushes the full set to the host as one [`SetPersonaEntries`]
  6	//! contribution. The granted directories arrive in the handshake's
  7	//! [`Welcome`] — the plugin never guesses paths.
  8	//!
  9	//! Wire behavior: `Hello` → (await `Welcome`) → one `SetPersonaEntries` →
 10	//! exit. The host keeps the contribution (published as `PersonasLoaded`)
 11	//! after guest end.
 12	//!
 13	//! Parse rules mirror the frozen on-disk format the host loader used:
 14	//! content must start (after leading whitespace) with `+++`, split at the
 15	//! first `\n+++`, the middle is TOML, the body is the remainder with
 16	//! leading newlines stripped and trailing whitespace trimmed. A file that
 17	//! fails to parse is skipped with a note on stderr — one bad file never
 18	//! drops the batch.
 19	
 20	use std::collections::BTreeMap;
 21	use std::path::Path;
 22	
 23	use error_stack::ResultExt as _;
 24	use jinn_plugin_api::{PersonaDef, PluginToHost, SetPersonaEntries};
 25	use jinn_plugin_sdk::{PluginOutput, hello, push, welcome};
 26	use serde::Deserialize;
 27	use wherror::Error;
 28	
 29	/// Persona-file parse failures (carried between parse helpers).
 30	#[derive(Debug, Error)]
 31	#[error(debug)]
 32	pub enum PersonaParseError {
 33	    /// Filesystem I/O failure.
 34	    Io,
 35	    /// Content does not start with `+++` or has no closing `+++`.
 36	    Frontmatter,
 37	    /// TOML parsing failed.
 38	    Parse,
 39	}
 40	
 41	/// Frontmatter schema for persona files.
 42	#[derive(Debug, Deserialize)]
 43	struct Frontmatter {
 44	    /// Unique persona name.
 45	    name: String,
 46	    /// Short description.
 47	    #[serde(default)]
 48	    description: String,
 49	}
 50	
 51	fn main() {
 52	    let mut out = PluginOutput::stdout();
 53	    if hello(&mut out, "persona-loader").is_err() {
 54	        return note_exit("handshake write failed");
 55	    }
 56	    let Ok(grants) = welcome() else {
 57	        return note_exit("no Welcome from host");
 58	    };
 59	
 60	    let personas = collect_personas(&grants.read_dirs);
 61	    if push(
 62	        &mut out,
 63	        PluginToHost::SetPersonaEntries(SetPersonaEntries { personas }),
 64	    )
 65	    .is_err()
 66	    {
 67	        note_exit("contribution write failed");
 68	    }
 69	}
 70	
 71	/// Writes a diagnostic to stderr (host-side diagnostics) and returns.
 72	fn note_exit(message: &str) {
 73	    eprintln!("persona-loader: {message}");
 74	}
 75	
 76	/// Scans the granted read dirs (earlier dirs shadow same-name later ones,
 77	/// matching the host's user-overrides-system rule) and collects every
 78	/// parseable persona keyed by name, sorted by name. Unparseable files are
 79	/// skipped with a note on stderr — one bad file never drops the batch.
 80	fn collect_personas(read_dirs: &[String]) -> Vec<PersonaDef> {
 81	    let mut defs = BTreeMap::new();
 82	    for dir in read_dirs {
 83	        merge_dir(&mut defs, Path::new(dir));
 84	    }
 85	    defs.into_values().collect()
 86	}
 87	
 88	/// Merges one directory's persona files into the accumulated set.
 89	fn merge_dir(defs: &mut BTreeMap<String, PersonaDef>, dir: &Path) {
 90	    let Ok(entries) = std::fs::read_dir(dir) else {
 91	        return;
 92	    };
 93	
 94	    for entry in entries.flatten() {
 95	        let path = entry.path();
 96	        if path.extension().is_none_or(|ext| ext != "md") {
 97	            continue;
 98	        }
 99	        match parse_persona_file(&path) {
100	            Ok(persona) => {
101	                defs.insert(persona.name.clone(), persona);
102	            }
103	            Err(report) => {
104	                let reason = report.current_context();
105	                eprintln!(
106	                    "persona-loader: skipping persona {}: {reason:?}",
107	                    path.display()
108	                );
109	            }
110	        }
111	    }
112	}
113	
114	/// Parses one persona file from disk.
115	///
116	/// # Errors
117	///
118	/// Returns an error if the file cannot be read or the frontmatter is malformed.
119	pub fn parse_persona_file(
120	    path: &Path,
121	) -> Result<PersonaDef, error_stack::Report<PersonaParseError>> {
122	    let content = std::fs::read_to_string(path)
123	        .change_context(PersonaParseError::Io)
124	        .attach(format!("failed to read {}", path.display()))?;
125	    parse_persona_content(&content)
126	}
127	
128	/// Parses persona content (testable without the filesystem).
129	///
130	/// # Errors
131	///
132	/// Returns an error if the content has no `+++` frontmatter or malformed TOML.
133	pub fn parse_persona_content(
134	    content: &str,
135	) -> Result<PersonaDef, error_stack::Report<PersonaParseError>> {
136	    let trimmed = content.trim_start();
137	
138	    let Some(after_open) = trimmed.strip_prefix("+++") else {
139	        return Err(error_stack::Report::new(PersonaParseError::Frontmatter)
140	            .attach("content must start with +++ frontmatter delimiter"));
141	    };
142	
143	    let Some((frontmatter_str, body_rest)) = after_open.split_once("\n+++") else {
144	        return Err(error_stack::Report::new(PersonaParseError::Frontmatter)
145	            .attach("missing closing +++ frontmatter delimiter"));
146	    };
147	
148	    let frontmatter: Frontmatter = toml::from_str(frontmatter_str.trim())
149	        .change_context(PersonaParseError::Parse)
150	        .attach("failed to parse frontmatter TOML")?;
151	
152	    let body = body_rest.trim_start_matches('\n').trim_end().to_owned();
153	
154	    Ok(PersonaDef {
155	        name: frontmatter.name,
156	        description: if frontmatter.description.is_empty() {
157	            None
158	        } else {
159	            Some(frontmatter.description)
160	        },
161	        body,
162	    })
163	}
164	
165	#[cfg(test)]
166	mod tests {
167	    #![allow(
168	        clippy::expect_used,
169	        clippy::panic,
170	        clippy::unreachable,
171	        clippy::indexing_slicing,
172	        reason = "test code"
173	    )]
174	    use super::*;
175	
176	    #[rstest::rstest]
177	    fn parse_persona_content_with_valid_frontmatter() {
178	        // Given a valid persona file content.
179	        let content = "+++\nname = \"coding-assistant\"\ndescription = \"Expert coder\"\n+++\n\nYou are an expert coding assistant.\n";
180	
181	        // When parsing.
182	        let persona = parse_persona_content(content).expect("parse");
183	
184	        // Then fields are correctly extracted.
185	        assert_eq!(persona.name, "coding-assistant");
186	        assert_eq!(persona.description.as_deref(), Some("Expert coder"));
187	        assert_eq!(persona.body, "You are an expert coding assistant.");
188	    }
189	
190	    #[rstest::rstest]
191	    fn parse_persona_content_without_description() {
192	        // Given a persona without description.
193	        let content = "+++\nname = \"minimal\"\n+++\n\nBody text here.";
194	
195	        // When parsing.
196	        let persona = parse_persona_content(content).expect("parse");
197	
198	        // Then description is absent on the wire.
199	        assert_eq!(persona.name, "minimal");
200	        assert_eq!(persona.description, None);
201	        assert_eq!(persona.body, "Body text here.");
202	    }
203	
204	    #[rstest::rstest]
205	    fn parse_persona_content_fails_without_frontmatter() {
206	        // Given content without +++ delimiter.
207	        let content = "Just some text without frontmatter.";
208	
209	        // When parsing.
210	        let result = parse_persona_content(content);
211	
212	        // Then it fails with Frontmatter.
213	        assert!(matches!(
214	            result.unwrap_err().current_context(),
215	            PersonaParseError::Frontmatter
216	        ));
217	    }
218	
219	    #[rstest::rstest]
220	    fn parse_persona_content_fails_without_closing_delimiter() {
221	        // Given content with opening +++ but no closing +++.
222	        let content = "+++\nname = \"test\"\nNo closing delimiter here.";
223	
224	        // When parsing.
225	        let result = parse_persona_content(content);
226	
227	        // Then it fails with Frontmatter.
228	        assert!(matches!(
229	            result.unwrap_err().current_context(),
230	            PersonaParseError::Frontmatter
231	        ));
232	    }
233	
234	    #[rstest::rstest]
235	    fn parse_persona_content_fails_with_invalid_toml() {
236	        // Given content with invalid TOML in frontmatter.
237	        let content = "+++\nname = invalid toml\n+++\n\nBody.";
238	
239	        // When parsing.
240	        let result = parse_persona_content(content);
241	
242	        // Then it fails with Parse.
243	        assert!(matches!(
244	            result.unwrap_err().current_context(),
245	            PersonaParseError::Parse
246	        ));
247	    }
248	
249	    #[rstest::rstest]
250	    fn parse_persona_content_preserves_multiline_body() {
251	        // Given a persona with multiline body.
252	        let content = "+++\nname = \"multi\"\n+++\n\nLine one.\nLine two.\nLine three.";
253	
254	        // When parsing.
255	        let persona = parse_persona_content(content).expect("parse");
256	
257	        // Then all body lines are preserved.
258	        assert!(persona.body.contains("Line one."));
259	        assert!(persona.body.contains("Line two."));
260	        assert!(persona.body.contains("Line three."));
261	    }
262	
263	    #[rstest::rstest]
264	    fn shipped_learning_tutor_persona_parses_with_its_grounding() {
265	        // Given the shipped learning-tutor persona bundled into the repo.
266	        let content = include_str!("../../../res/personas/learning-tutor.md");
267	
268	        // When parsing it.
269	        let persona = parse_persona_content(content).expect("parse");
270	
271	        // Then it keeps its shipped name and an evidence-grounded description.
272	        assert_eq!(persona.name, "learning-tutor");
273	        assert!(
274	            persona
275	                .description
276	                .as_deref()
277	                .is_some_and(|d| d.contains("intelligent-tutoring"))
278	        );
279	    }
280	
281	    #[rstest::rstest]
282	    fn collect_personas_returns_sorted_personas() {
283	        // Given a directory with persona files.
284	        let dir = tempfile::TempDir::new().expect("temp dir");
285	
286	        std::fs::write(
287	            dir.path().join("beta.md"),
288	            "+++\nname = \"beta\"\ndescription = \"B\"\n+++\n\nBeta body.",
289	        )
290	        .expect("write");
291	        std::fs::write(
292	            dir.path().join("alpha.md"),
293	            "+++\nname = \"alpha\"\ndescription = \"A\"\n+++\n\nAlpha body.",
294	        )
295	        .expect("write");
296	
297	        // When collecting.
298	        let personas = collect_personas(&[dir.path().to_string_lossy().into_owned()]);
299	
300	        // Then personas are sorted by name.
301	        assert_eq!(personas.len(), 2);
302	        assert_eq!(personas[0].name, "alpha");
303	        assert_eq!(personas[1].name, "beta");
304	    }
305	
306	    #[rstest::rstest]
307	    fn collect_personas_returns_empty_for_missing_dir() {
308	        // Given a nonexistent directory.
309	        // When collecting.
310	        let personas = collect_personas(&["/nonexistent/path".to_owned()]);
311	
312	        // Then an empty vec is returned.
313	        assert!(personas.is_empty());
314	    }
315	
316	    #[rstest::rstest]
317	    fn collect_personas_skips_invalid_files() {
318	        // Given a directory with one valid and one invalid file.
319	        let dir = tempfile::TempDir::new().expect("temp dir");
320	
321	        std::fs::write(
322	            dir.path().join("valid.md"),
323	            "+++\nname = \"valid\"\ndescription = \"V\"\n+++\n\nValid body.",
324	        )
325	        .expect("write");
326	        std::fs::write(dir.path().join("invalid.md"), "Not a valid persona file.").expect("write");
327	
328	        // When collecting.
329	        let personas = collect_personas(&[dir.path().to_string_lossy().into_owned()]);
330	
331	        // Then only the valid persona is returned.
332	        assert_eq!(personas.len(), 1);
333	        assert_eq!(personas[0].name, "valid");
334	    }
335	
336	    #[rstest::rstest]
337	    fn collect_personas_ignores_non_md_files() {
338	        // Given a directory with a .txt file.
339	        let dir = tempfile::TempDir::new().expect("temp dir");
340	
341	        std::fs::write(
342	            dir.path().join("notes.txt"),
343	            "+++\nname = \"hidden\"\ndescription = \"H\"\n+++\n\nBody.",
344	        )
345	        .expect("write");
346	
347	        // When collecting.
348	        let personas = collect_personas(&[dir.path().to_string_lossy().into_owned()]);
349	
350	        // Then no personas are found.
351	        assert!(personas.is_empty());
352	    }
353	}

  1	//! The first-party themes plugin.
  2	//!
  3	//! Scans the granted themes directories for `*.toml` files, parses each
  4	//! through the same loader core uses, and pushes the full set to the host
  5	//! as one [`SetThemeEntries`] contribution. The granted directories arrive
  6	//! in the handshake's [`Welcome`] — the plugin never guesses paths.
  7	//!
  8	//! Wire behavior: `Hello` → (await `Welcome`) → one `SetThemeEntries` →
  9	//! exit. The host keeps the contribution cached after guest end.
 10	
 11	use std::collections::BTreeMap;
 12	use std::path::Path;
 13	
 14	use jinn_plugin_api::{PluginToHost, SetThemeEntries, THEME_COLOR_SLOTS, ThemeColorSlot, ThemeDef};
 15	use jinn_plugin_sdk::{PluginOutput, hello, push, welcome};
 16	use jinn_theme::color::ThemeColor;
 17	use jinn_theme::loader::{ThemeError, discover_themes, load_theme_from_file};
 18	
 19	/// Theme-load failures carried between scan helpers.
 20	type ThemeReport = error_stack::Report<ThemeError>;
 21	
 22	fn main() {
 23	    let mut out = PluginOutput::stdout();
 24	    if hello(&mut out, "theme-loader").is_err() {
 25	        return note_exit("handshake write failed");
 26	    }
 27	    let Ok(grants) = welcome() else {
 28	        return note_exit("no Welcome from host");
 29	    };
 30	
 31	    let themes = collect_themes(&grants.read_dirs);
 32	    if push(
 33	        &mut out,
 34	        PluginToHost::SetThemeEntries(SetThemeEntries { themes }),
 35	    )
 36	    .is_err()
 37	    {
 38	        note_exit("contribution write failed");
 39	    }
 40	}
 41	
 42	/// Writes a diagnostic to stderr (host-side diagnostics) and returns.
 43	fn note_exit(message: &str) {
 44	    eprintln!("theme-loader: {message}");
 45	}
 46	
 47	/// Scans the granted read dirs (earlier dirs shadow same-name later ones,
 48	/// matching the user-overrides-system rule core had) and translates each
 49	/// loadable theme to its wire shape. Unloadable files are skipped with a
 50	/// note on stderr — one bad file never drops the batch.
 51	fn collect_themes(read_dirs: &[String]) -> Vec<ThemeDef> {
 52	    let mut defs = BTreeMap::new();
 53	    for dir in read_dirs {
 54	        let dir = Path::new(dir);
 55	        match discover_themes(dir) {
 56	            Ok(found) => merge_dir(&mut defs, dir, &found),
 57	            Err(report) => note_scan_failure(dir, &report),
 58	        }
 59	    }
 60	    defs.into_values().collect()
 61	}
 62	
 63	/// Merges one directory's discoveries into the accumulated set.
 64	fn merge_dir(
 65	    defs: &mut BTreeMap<String, ThemeDef>,
 66	    dir: &Path,
 67	    found: &[(String, std::path::PathBuf)],
 68	) {
 69	    for (name, path) in found {
 70	        match load_theme_from_file(path) {
 71	            Ok(theme) => {
 72	                defs.insert(name.clone(), to_def(name, &theme));
 73	            }
 74	            Err(report) => note_theme_failure(dir, name, &report),
 75	        }
 76	    }
 77	}
 78	
 79	/// Notes one theme's load failure on stderr (host-side diagnostics).
 80	fn note_theme_failure(dir: &Path, name: &str, report: &ThemeReport) {
 81	    eprintln!(
 82	        "theme-loader: skipping theme {name} in {}: {report}",
 83	        dir.display()
 84	    );
 85	}
 86	
 87	/// Notes one directory's scan failure on stderr.
 88	fn note_scan_failure(dir: &Path, report: &ThemeReport) {
 89	    eprintln!("theme-loader: cannot scan {}: {report}", dir.display());
 90	}
 91	
 92	/// Converts one resolved core theme to its wire shape.
 93	fn to_def(name: &str, theme: &jinn_theme::Theme) -> ThemeDef {
 94	    let mut colors = BTreeMap::new();
 95	    for &slot in THEME_COLOR_SLOTS {
 96	        let color = slot_color(theme, slot);
 97	        colors.insert(slot.key().to_owned(), color);
 98	    }
 99	    ThemeDef {
100	        name: name.to_owned(),
101	        description: None,
102	        colors,
103	    }
104	}
105	
106	/// One slot's color rendered in a format the wire accepts (hex or ANSI name).
107	fn slot_color(theme: &jinn_theme::Theme, slot: ThemeColorSlot) -> String {
108	    let color = match slot {
109	        ThemeColorSlot::FocusAccent => theme.focus_accent,
110	        ThemeColorSlot::BorderUnfocused => theme.border_unfocused,
111	        ThemeColorSlot::PopupTitle => theme.popup_title,
112	        ThemeColorSlot::PrimaryText => theme.primary_text,
113	        ThemeColorSlot::MutedText => theme.muted_text,
114	        ThemeColorSlot::SubagentFg => theme.subagent_fg,
115	        ThemeColorSlot::ErrorText => theme.error_text,
116	        ThemeColorSlot::Success => theme.success,
117	        ThemeColorSlot::Warning => theme.warning,
118	        ThemeColorSlot::Streaming => theme.streaming,
119	        ThemeColorSlot::GutterBg => theme.gutter_bg,
120	        ThemeColorSlot::GutterContextIncluded => theme.gutter_context_included,
121	        ThemeColorSlot::UserBlockBg => theme.user_block_bg,
122	        ThemeColorSlot::ToolFg => theme.tool_fg,
123	        ThemeColorSlot::ToolSuccessBg => theme.tool_success_bg,
124	        ThemeColorSlot::ToolFailureBg => theme.tool_failure_bg,
125	        ThemeColorSlot::ToolPendingBg => theme.tool_pending_bg,
126	        ThemeColorSlot::ChallengeAlertBg => theme.challenge_alert_bg,
127	        ThemeColorSlot::ChallengeAlertFg => theme.challenge_alert_fg,
128	        ThemeColorSlot::CompactionBlockBg => theme.compaction_block_bg,
129	        ThemeColorSlot::TruncationFg => theme.truncation_fg,
130	        ThemeColorSlot::PickerActiveMarker => theme.picker_active_marker,
131	        ThemeColorSlot::PickerSelectedBg => theme.picker_selected_bg,
132	        ThemeColorSlot::PickerHighlightBg => theme.picker_highlight_bg,
133	        ThemeColorSlot::TabActiveFg => theme.tab_active_fg,
134	        ThemeColorSlot::TabActiveBg => theme.tab_active_bg,
135	        ThemeColorSlot::TabInactiveFg => theme.tab_inactive_fg,
136	        ThemeColorSlot::SelectionFg => theme.selection_fg,
137	        ThemeColorSlot::SelectionBg => theme.selection_bg,
138	        ThemeColorSlot::AccentAction => theme.accent_action,
139	        ThemeColorSlot::AgeFresh => theme.age_fresh,
140	        ThemeColorSlot::AgeStale => theme.age_stale,
141	        ThemeColorSlot::ScrollIndicatorBg => theme.scroll_indicator_bg,
142	        ThemeColorSlot::SidebarResizeAccent => theme.sidebar_resize_accent,
143	        ThemeColorSlot::InputModeQueue => theme.input_mode_queue,
144	        ThemeColorSlot::InputModeSteer => theme.input_mode_steer,
145	        ThemeColorSlot::InfopopupBg => theme.infopopup_bg,
146	        ThemeColorSlot::InfopopupTitle => theme.infopopup_title,
147	        ThemeColorSlot::InfopopupBorder => theme.infopopup_border,
148	        ThemeColorSlot::InfopopupFg => theme.infopopup_fg,
149	        ThemeColorSlot::QuakeBarBg => theme.quake_bar_bg,
150	    };
151	    ThemeColor::from(color).to_string()
152	}

  1	//! The first-party URL-citations plugin.
  2	//!
  3	//! Subscribes to `tool_call` / `tool_result` / `turn_end` host events and
  4	//! detects citable web sources by shape (see [`detect`]): URLs appearing in
  5	//! tool-call arguments, and `{url/link, title}` objects in successful
  6	//! tool-result JSON — both descended into strings that embed further JSON,
  7	//! bounded — plus one builtin `web-search` carve-out that rebuilds the
  8	//! DuckDuckGo re-run URL from the query. Detected citations accumulate in a
  9	//! per-session buffer, deduplicated by URL, and flush as one
 10	//! `PushCitations` contribution when a turn reaches a final answer.
 11	//!
 12	//! Wire behavior: `Hello` (with subscriptions) → (await `Welcome`) → event
 13	//! loop until stdin closes.
 14	
 15	mod detect;
 16	
 17	use std::collections::HashMap;
 18	use std::io::BufRead as _;
 19	
 20	use jinn_plugin_api::{
 21	    HostToPlugin, PluginCitation, PluginToHost, PluginToHostOrHostToPlugin, PushCitations,
 22	    ToolCallEvent, ToolResultEvent, TurnEndEvent,
 23	};
 24	use jinn_plugin_sdk::{PluginOutput, hello_with_subscriptions, push, welcome};
 25	
 26	/// Turn-scoped detection state: pending call-rule candidates and the
 27	/// per-session citation buffer.
 28	struct CitationState {
 29	    /// Call-rule candidates keyed by `tool_call_id`, awaiting their result.
 30	    pending: HashMap<String, Vec<PluginCitation>>,
 31	    /// Confirmed citations per session, deduplicated by URL, in order.
 32	    buffer: HashMap<String, Vec<PluginCitation>>,
 33	}
 34	
 35	impl CitationState {
 36	    fn new() -> Self {
 37	        Self {
 38	            pending: HashMap::new(),
 39	            buffer: HashMap::new(),
 40	        }
 41	    }
 42	
 43	    /// Stashes call-rule candidates (and the `web-search` carve-out) for a
 44	    /// tool call, keyed by its id.
 45	    fn on_tool_call(&mut self, event: &ToolCallEvent) {
 46	        let mut candidates = Vec::new();
 47	        if event.name == "web-search"
 48	            && let Some(citation) = detect::ddg_citation(&event.arguments)
 49	        {
 50	            candidates.push(citation);
 51	        }
 52	        for url in detect::urls_from_call_args(&event.arguments) {
 53	            candidates.push(PluginCitation {
 54	                url,
 55	                title: String::new(),
 56	                content: None,
 57	            });
 58	        }
 59	        if !candidates.is_empty() {
 60	            self.pending.insert(event.tool_call_id.clone(), candidates);
 61	        }
 62	    }
 63	
 64	    /// Promotes pending candidates on success, extracts result-rule
 65	    /// citations, and stashes both into the session buffer (deduped).
 66	    fn on_tool_result(&mut self, event: &ToolResultEvent) {
 67	        if !event.success {
 68	            // A failed call is not citable — drop its candidates.
 69	            self.pending.remove(&event.tool_call_id);
 70	            return;
 71	        }
 72	        let mut citations = self.pending.remove(&event.tool_call_id).unwrap_or_default();
 73	        for citation in detect::citations_from_result_content(&event.content) {
 74	            citations.push(citation);
 75	        }
 76	        self.record(&event.session_id, citations);
 77	    }
 78	
 79	    /// Flushes and returns the session's buffered citations on a final
 80	    /// answer; retains them otherwise (a later successful turn still
 81	    /// surfaces the sources).
 82	    fn on_turn_end(&mut self, event: &TurnEndEvent) -> Option<Vec<PluginCitation>> {
 83	        if !event.final_answer {
 84	            return None;
 85	        }
 86	        let citations = self.buffer.remove(&event.session_id)?;
 87	        (!citations.is_empty()).then_some(citations)
 88	    }
 89	
 90	    /// Appends citations to the session buffer, deduplicating by URL.
 91	    fn record(&mut self, session_id: &str, citations: Vec<PluginCitation>) {
 92	        let buffered = self.buffer.entry(session_id.to_owned()).or_default();
 93	        for citation in citations {
 94	            // The call rule stashes URLs with an empty title; a later
 95	            // same-URL citation with a real title wins.
 96	            if let Some(existing) = buffered.iter_mut().find(|c| c.url == citation.url) {
 97	                if existing.title.is_empty() {
 98	                    *existing = citation;
 99	                }
100	                continue;
101	            }
102	            buffered.push(citation);
103	        }
104	    }
105	}
