107	fn main() {
108	    let mut out = PluginOutput::stdout();
109	    if hello_with_subscriptions(
110	        &mut out,
111	        "url-citations",
112	        &["tool_call", "tool_result", "turn_end"],
113	    )
114	    .is_err()
115	    {
116	        return;
117	    }
118	    if welcome().is_err() {
119	        return;
120	    }
121	
122	    // Ordering assumption (documented per the task spec): the host forwards
123	    // `tool_call`/`tool_result` synchronously along the tool loop, and this
124	    // plugin processes them and pushes `PushCitations` before the next LLM
125	    // dispatch begins — so a flush at `turn_end` always lands within the
126	    // correct turn. If citations ever appear in the WRONG turn's footer,
127	    // this assumption has been violated (e.g. the forwarder or this guest
128	    // added buffering/async hops); re-synchronize before adding retries.
129	    let mut state = CitationState::new();
130	    let stdin = std::io::stdin();
131	    let mut lines = stdin.lock().lines();
132	    while let Some(Ok(line)) = lines.next() {
133	        let Ok(envelope) = serde_json::from_str::<jinn_plugin_api::Envelope>(&line) else {
134	            continue;
135	        };
136	        let event = match envelope.msg {
137	            PluginToHostOrHostToPlugin::Host(event) => event,
138	            _ => continue,
139	        };
140	        match event {
141	            HostToPlugin::ToolCallEvent(e) => state.on_tool_call(&e),
142	            HostToPlugin::ToolResultEvent(e) => state.on_tool_result(&e),
143	            HostToPlugin::TurnEndEvent(e) => {
144	                if let Some(citations) = state.on_turn_end(&e) {
145	                    let _ = push(
146	                        &mut out,
147	                        PluginToHost::PushCitations(PushCitations {
148	                            session_id: e.session_id.clone(),
149	                            citations,
150	                        }),
151	                    );
152	                }
153	            }
154	            HostToPlugin::Welcome(_) => {}
155	        }
156	    }
157	}
